import path from 'node:path';
export async function assertAssociationFeedback({page,frame,box,check,out}){
 const status=box.locator('.product-link-feedback'),confirm=box.locator('.product-link-controls > button.primary'),search=box.getByLabel('搜索网站商品'),select=box.getByLabel('网站对应商品');let release,entered,count=0,fail=true;const gate=new Promise(r=>release=r),started=new Promise(r=>entered=r);
 const handler=async route=>{let p;try{p=route.request().postDataJSON();}catch{}if(p?.action!=='website-link')return route.fallback();count++;if(fail){entered();await gate;return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({ok:false,error:{message:'虚构网站连接超时：未能读取商品 ID 9001'}})});}return route.continue();};
 await page.route('**/api/**',handler);
 try{
  await page.setViewportSize({width:820,height:640});await confirm.click();await status.filter({hasText:'请选择一个网站商品'}).waitFor();check(count===0,'未选择时明确提示原因且不发送关联请求');
  await search.fill('9001');await select.selectOption('9001');await Promise.all([confirm.click(),started]);check(await confirm.textContent()==='正在关联…'&&await confirm.getAttribute('aria-busy')==='true','确认关联立即显示处理中及忙碌状态');check(await confirm.isDisabled()&&await box.getByRole('button',{name:'取消',exact:true}).isDisabled(),'关联提交中防重复且禁止中断保存');await confirm.evaluate(b=>{b.click();b.click();});check(count===1,'关联处理中重复点击不会重复请求');await page.keyboard.press('Escape');check(await box.isVisible(),'提交中Esc不能关闭正在保存的弹窗');await page.screenshot({path:path.join(out,'association-pending-820.png')});release();await status.locator('[data-state=error]').count();await box.locator('.product-link-feedback[data-state=error]').waitFor();check((await status.textContent()).includes('虚构网站连接超时'),'失败显示真实原因并保留所选商品');check(await select.inputValue()==='9001'&&!await confirm.isDisabled(),'失败后保留选择并可重试');const r=await status.boundingBox(),button=await confirm.boundingBox();check(r.y>=0&&r.y+r.height<=640&&button.y+button.height<=640,'窄短窗口错误与确认按钮同时可见');check(await status.getAttribute('role')==='alert','失败原因可由辅助技术立即读取');await page.screenshot({path:path.join(out,'association-failed-820.png')});
  await box.getByRole('button',{name:'重新读取候选',exact:true}).click();await status.filter({hasText:'候选已更新'}).waitFor();check(await select.inputValue()==='9001','重新读取候选保留仍有效的人工选择');
  fail=false;await confirm.click();await box.locator('.product-link-feedback[data-state=success]').waitFor();check((await status.textContent()).includes('关联成功')&&(await status.textContent()).includes('9001'),'成功明确显示商品及网站ID');check(await confirm.textContent()==='已关联'&&await confirm.isDisabled(),'成功按钮显示已关联，不能重复提交');await page.screenshot({path:path.join(out,'association-success-820.png')});await box.getByRole('button',{name:'完成',exact:true}).click();await frame.getByRole('button',{name:'同步网站图片',exact:true}).waitFor();check((await frame.locator('.product-identifiers').textContent()).includes('9001'),'完成后详情即时显示已保存的网站ID');
 }finally{release();await page.unroute('**/api/**',handler);await page.setViewportSize({width:1280,height:820});}
}
